from pathlib import Path
import base64, csv, datetime, hashlib, html, json, re, sys
from urllib.parse import quote

root=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else Path(__file__).resolve().parents[2]
a=root/'analysis'; guide=root/'치주질환과 고혈압 - 분석 길잡이'; out=root/'analysis-process.html'
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def rows(p):
    with p.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def esc(s):return html.escape(str(s),quote=True)
source_refs={}
def ref(path,label):
    p=root/path
    assert p.exists(),path
    source_refs[path]=sha(p)
    return f'<a class="evidence" href="{quote(path,safe="/")}">{esc(label)}<span aria-hidden="true"> ↗</span></a>'
def note(n):return next(guide.glob(f'{n:02d}-paper*.md')).relative_to(root).as_posix()
def refs(*items):return '<div class="sources">'+''.join(ref(p,l) for p,l in items)+'</div>'
report=load(a/'runs/E2-20261004/report.json')
core=load(a/'runs/R2-20261004/report.json')
comparison=rows(a/'comparisons/E2-20261004/all_published_OR_comparisons.csv')
fisher=rows(a/'runs/V1-20261004/typeI_error.csv')
effect=rows(a/'runs/V1-20261004/published_OR_PR.csv')
assert report['qa_core']['analysis_n']==21458 and len(comparison)==84
matched=sum(x['within_OR_rounding'].lower()=='true' for x in comparison)
assert matched==7,matched
for p in ('analysis/runs/E2-20261004/report.json','analysis/runs/R2-20261004/report.json','analysis/comparisons/E2-20261004/all_published_OR_comparisons.csv','analysis/runs/V1-20261004/typeI_error.csv','analysis/runs/V1-20261004/published_OR_PR.csv'):
    source_refs[p]=sha(root/p)
prompt='执行'
prompt_path='실행 설계/05-prompts-v2.0-original.md';week_path='실행 설계/05-prompts-week5.md'
prompt_map=[
('01','시작 점검과 프로젝트 계약','논문·과제·범위·환경을 먼저 고정한다.','지정 PMID를 확인하고, NHANES 공개 자료·R 분석·uv 보조·필수 산출물을 project.json에 등록했다.', [('analysis/memory/project.json','프로젝트 계약'),('analysis/environment/ENV2-20261004/environment.json','환경 기록')]),
('02','추론 흐름을 먼저 설명','원자료 → 코딩 → 선정 → 요약 → 모형 → 해석을 concept/paper 쌍으로 만든다.','7단계 이론·논문 노트를 만들고, 자가보고 OHQ·복합표본·보정 OR의 의미를 구분했다.',[(note(1),'연구 질문'),('analysis/memory/stage_registry.json','단계 등록부')]),
('03','의문을 분석 작업으로 전환','저자 설정 조사(R)와 통계적 타당성 검토(V)를 구분한다.','ISSUE-01~12를 기록하고 R2/E1/E2 재구성과 V1 과제 검증을 분리했다. 원문 수치의 근접도와 방법의 타당성을 같은 판정으로 읽지 않는다.',[('analysis/memory/task_registry.json','작업 계약'),('analysis/memory/output_coverage.json','요구사항 연결')]),
('04','역할과 독립성','조정·논문·계획·환경·구현·검토 역할을 나누고 정확한 결과를 검토한다.','별도 인스턴스에서 자료·모형·검증을 감사했다. 같은 원자료를 검토한 것이며 새 외부 표본 검증은 아니다. 출판 결과 노출로 비맹검이었다.',[('analysis/reviews/E2-20261004-q-review.json','E2 수치 검토'),('analysis/reviews/E2-20261004-data-review.json','E2 자료 검토')]),
('05','작업 계약·소통·메모리','계획·가정·허용 입력·노출 이력·판정 기준과 변경 사유를 기록한다.','plan과 task packet, decisions, review에 근거를 남겼다. OR/CI 허용오차 0.005·정수 n 오차 0을 정했다. 일부 과거 절대경로는 이동 전 위치를 보존한다.',[('analysis/memory/decisions.md','결정 기록'),('analysis/config/plan-v1.5.json','최종 계획')]),
('06','변경·실패·재개','실패를 보존하고 상류 정의가 바뀌면 영향을 받는 하류를 갱신한다.','R1 헤더 오류를 새 R2에서 수정했다. E1 이후 J 검사법 차이를 확인하고 plan1.5를 검토한 뒤 E2를 실행했다. M1/M2는 재사용하고 M3 등은 재계산했다.',[('analysis/runs/R1-20261004/status.json','R1 실패 기록'),('analysis/runs/E2-20261004/artifact_dependencies.csv','결과 의존 관계')]),
('07','파일 구조와 소유권','tasks는 작업·인계, runs는 계산, memory는 조정, assets는 검토된 그림 사본으로 둔다.','원자료·실행을 덮어쓰지 않고 run별 표·그림·로그를 보존했다. 학습 문서 이미지 10개는 원본 그림과 해시를 대조했다.',[('analysis/README.md','실행·폴더 안내'),('치주질환과 고혈압 - 분석 길잡이/assets/manifest.json','이미지 해시')]),
('08','기존 학습 문서에 통합','초기 설명과 의문을 보존하고 구현·비교·검토·갱신 해석을 해당 단계에 붙인다.','01~07-paper에 결과를 반영하고 문서 검토를 받았다. 이 HTML은 2026-10-06 사용자 요청에 따른 후속 설명 자료이며 당시 분석을 새로 실행한 결과가 아니다.',[(note(7),'통합된 해석'),('analysis/reviews/final-learning-note-review.json','학습 문서 검토')]),
('09','완료 판정','필수 항목의 구현·검토·문서 연결과 정확 재현 여부를 별도로 판정한다.','정의 가능한 필수 범위는 완료했지만 최종 판정은 부분 재현이다. 선택 사항인 공통 완전사례 분석은 실행하지 않았고 저자 설정 질문은 남았다.',[('analysis/memory/output_coverage.json','완료 범위 추적'),('analysis/memory/progress.md','완료·미실행 범위')])]

issues=[
('01','과제의 “구강검진”과 논문의 측정이 같은가?','해결','원문은 자가보고 OHQ835·OHQ845이다. 임상 치주검진을 재현했다고 부르지 않는다.','측정 방식은 확인했지만 자가보고의 측정오류는 남는다.',1),
('02','혈압 평균과 약물 문항의 skip을 어떻게 처리하는가?','부분 해결','유효한 모든 1~4회 SBP/DBP를 평균하고, 진단·치료·측정의 양성 근거를 합쳤다. 구조적 약물 skip은 분기 근거로 구분했다.','공식 응답 의미를 확인한 분석자 후보다. 저자의 정확한 평균·분기 코드와 같다는 증거는 없다.',2),
('03','흡연 Yes/No는 평생흡연인가 현재흡연인가?','부분 해결','기본 후보는 SMQ020의 평생 100개비 이상 여부를 사용했고 코드 의미는 확인했다.','저자의 실제 흡연 정의가 미공개이므로 현재흡연과 같은 뜻으로 읽지 않는다.',2),
('04','논문 N=21,800을 정확히 만들 수 있는가?','미해결','선정 흐름을 계산했지만 최종 21,458명으로 342명 적다.','누가 어떤 규칙으로 제외됐는지 저자의 코드 없이 확정할 수 없다.',3),
('05','식이·TG 자료에 어느 가중치를 써야 하는가?','부분 해결','A=MEC/5, B=day1 식이 가중치/5로 구분했다. TG는 BIOPRO LBXSTR 비공복 후보다.','B는 표본과 가중치가 함께 바뀐다. 저자의 TG 변수·공복 제한·가중치 선택과 같은지 미확인이다.',3),
('06','일반 Fisher와 survey 검정은 같은 질문에 답하는가?','해결 범위 명시','비가중 Pearson/Yates/Fisher는 교육 비교, Rao–Scott는 설계 기반 추론으로 구분했다.','작은 p를 이유로 우월한 검정을 고르지 않는다. 원문의 survey χ² 구현 상세는 미확인이다.',4),
('07','공변량·결측 처리·모형 설정을 복원할 수 있는가?','부분 해결','본문 Table2·Table3와 보충표 각주를 각각 적용했다. 범주 Missing, 연속 중앙값+지시변수는 분석자 후보다.','저자의 대체값·흡연·당뇨 매핑 등 미공개 설정은 확정하지 못했다.',5),
('08','보정 OR는 인과효과이고 모형 간 변화는 교란 제거인가?','한계 유지','횡단면 연관, 자가보고, 잔여교란·역인과·선정 편향과 OR 비축약성을 고려했다.','인과효과를 식별하거나 편향이 제거됐음을 입증한 분석이 아니다.',5),
('09','Fisher의 명목 5%가 실제 기각확률과 같은가?','조건 내 해결','독립 이항 시나리오를 정확 열거하고 조건당 10,000회 MC로 검산했다.','정한 귀무 p·집단당 n의 결과다. 모든 귀무공간의 최대 size나 NHANES 표집 모의실험은 아니다.',6),
('10','흔한 결과에서 OR를 RR처럼 읽으면 얼마나 다른가?','조건 내 해결','출판 비가중 분할표의 crude OR=1.14835와 PR=1.06922를 비교했다.','두 배수의 상대 차이는 약 7.40%다. 발생 위험 증가율이나 보정 OR→RR 변환으로 읽지 않는다.',6),
('11','이 NHANES 자료에 McNemar를 적용할 수 있는가?','실자료 해당 없음','짝지은 전후 자료가 없어 실제 분석에 적용하지 않았다. 강의의 가상 100명 표로만 검증했다.','가상 paired 예제 결과를 NHANES 연구의 증거로 연결하지 않는다.',6),
('12','상류 정의가 바뀌면 표·모형·그림·노트도 같이 바뀌는가?','검토 범위 내 해결','E2에서 관련 M3·추세·상호작용·검사값 기술표·forest를 갱신하고 재사용 출처를 기록했다.','해시는 같은 파일이라는 확인이다. 모든 과학적 가정의 타당성이나 외부 일반화를 보장하지 않는다.',7)]

def section_label(num,short,title,intro):return f'<div class="section-heading"><span class="section-no">{num}</span><div><p class="eyebrow">{short}</p><h2>{title}</h2><p class="lede">{intro}</p></div></div>'
def figure(run,name,title,caption):
    path=f'치주질환과 고혈압 - 분석 길잡이/assets/{run}/{name}.png'
    p=root/path;assert p.exists();source_refs[path]=sha(p)
    data=base64.b64encode(p.read_bytes()).decode()
    return f'<figure><figcaption><h3>{title}</h3><span class="run-label">{run}</span><p>{caption}</p></figcaption><img src="data:image/png;base64,{data}" alt="{esc(title+". "+caption)}" loading="lazy" decoding="async">{refs((path,"원본 PNG"))}</figure>'

